function lateFee(amount: number, daysLate: number): number {
  if (daysLate <= 14) {
    return 0;
  }
  const fee = amount * 0.035 * Math.min(daysLate - 14, 60);
  return fee > 250 ? 250 : Math.round(fee * 100) / 100;
}

function formatCurrency(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

function applyDiscount(price: number, percent: number): number {
  const capped = Math.min(percent, MAX_DISCOUNT_PERCENT);
  return price - (price * capped) / 100;
}

interface OrderRow {
  id: string;
  customer: string;
  cents: number;
}

async function importOrders(
  csv: string,
  db: { save(row: OrderRow): Promise<void> },
): Promise<string> {
  const rows: OrderRow[] = [];
  for (const line of csv.split("\n")) {
    const [id, customer, cents] = line.split(",");
    if (!id || !customer || cents === undefined) continue;
    const value = Number(cents);
    if (Number.isNaN(value) || value < 0) continue;
    rows.push({ id: id.trim(), customer: customer.trim(), cents: value });
  }
  const seen = new Set<string>();
  const unique = rows.filter((row) => {
    if (seen.has(row.id)) return false;
    seen.add(row.id);
    return true;
  });
  for (const row of unique) {
    await db.save(row);
  }
  const totals = new Map<string, number>();
  for (const row of unique) {
    totals.set(row.customer, (totals.get(row.customer) ?? 0) + row.cents);
  }
  const lines: string[] = ["Customer | Total", "--- | ---"];
  for (const [customer, cents] of [...totals.entries()].sort(
    (a, b) => b[1] - a[1],
  )) {
    lines.push(`${customer} | $${(cents / 100).toFixed(2)}`);
  }
  const grand = unique.reduce((sum, row) => sum + row.cents, 0);
  lines.push("");
  lines.push(`Imported ${unique.length} orders, $${(grand / 100).toFixed(2)}`);
  return lines.join("\n");
}

interface InvoiceLine {
  description: string;
  quantity: number;
  unitCents: number;
}

function renderInvoiceText(
  number: string,
  customer: string,
  lines: InvoiceLine[],
): string {
  const out: string[] = [];
  out.push(`Invoice ${number}`);
  out.push(`Customer: ${customer}`);
  out.push("");
  out.push("Item | Qty | Unit | Amount");
  out.push("--- | --- | --- | ---");
  let total = 0;
  for (const line of lines) {
    const amount = line.quantity * line.unitCents;
    total += amount;
    const unit = (line.unitCents / 100).toFixed(2);
    out.push(
      `${line.description} | ${line.quantity} | $${unit} | $${(amount / 100).toFixed(2)}`,
    );
  }
  out.push("");
  out.push(`Total: $${(total / 100).toFixed(2)}`);
  return out.join("\n");
}

function clampPercent(value: number): number {
  const lowest = 0;
  const highest = 100;
  if (Number.isNaN(value)) {
    return lowest;
  }
  if (value < lowest) {
    return lowest;
  }
  if (value > highest) {
    return highest;
  }
  return Math.round(value);
}

function activeWithTag(
  items: { tags: string[]; active: boolean }[],
  tag: string,
) {
  return items.filter((item) => item.active && item.tags.includes(tag));
}

async function registerUser(
  form: { email: string; password: string; name: string },
  store: { insert(user: object): Promise<void> },
  analytics: { track(event: string, props: object): void },
): Promise<{ ok: boolean; message: string }> {
  const email = form.email.trim().toLowerCase();
  if (!email.includes("@") || email.length > 120) {
    return { ok: false, message: "Enter a valid email address." };
  }
  if (form.password.length < 10 || form.password === form.password.toLowerCase()) {
    return { ok: false, message: "Use a longer password with a capital letter." };
  }
  let hash = 5381;
  for (const char of form.password) {
    hash = (hash * 33) ^ char.charCodeAt(0);
  }
  await store.insert({
    id: `u_${email}`,
    email,
    name: form.name.trim(),
    passwordHash: String(hash >>> 0),
  });
  const greeting = form.name.trim() ? `Hi ${form.name.trim()},` : "Hi,";
  const body = [greeting, "", "Welcome aboard.", "Confirm your address to get started."].join("\n");
  analytics.track("signup", { domain: email.split("@")[1], length: body.length });
  return { ok: true, message: body };
}

function summarize(
  orders: { total: number; refunded: number }[],
  returns: { total: number; refunded: number }[],
) {
  let orderTotal = 0;
  let orderRefunded = 0;
  for (const order of orders) {
    orderTotal += order.total;
    orderRefunded += order.refunded;
  }
  const orderNet = orderTotal - orderRefunded;
  let returnTotal = 0;
  let returnRefunded = 0;
  for (const item of returns) {
    returnTotal += item.total;
    returnRefunded += item.refunded;
  }
  const returnNet = returnTotal - returnRefunded;
  return { orderNet, returnNet };
}

function average(values: number[]): number {
  if (values.length === 0) return 0;
  let sum = 0;
  for (const value of values) sum += value;
  return sum / values.length;
}

function slugify(text: string): string {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function truncate(text: string, length: number): string {
  return text.length <= length ? text : `${text.slice(0, length - 1)}…`;
}

function describeTotal(values: number[], label: string): string {
  let total = 0;
  for (const value of values) {
    total += value;
  }
  return `${label}: ${total}`;
}

